,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT ''\0625\062C\0645\0627\0644\064A \0627\0644\0645\0646\062A\062C\0627\062A'' TITLE, COUNT(*) BODY, ''\D83D\DCE6'' ICON'),
'FROM PRODUCTS',
'UNION ALL',
unistr('SELECT ''\0645\0646\062A\062C\0627\062A \0645\0646\062E\0641\0636\0629 \0627\0644\0645\062E\0632\0648\0646'', COUNT(*), ''\26A0\FE0F'''),
'FROM V_PRODUCT_STOCK',
'WHERE CURRENT_STOCK <= MIN_STOCK_LEVEL',
'UNION ALL',
unistr('SELECT ''\0625\062C\0645\0627\0644\064A \0642\064A\0645\0629 \0627\0644\0645\062E\0632\0648\0646'', SUM(UNIT_PRICE * CURRENT_STOCK), ''\D83D\DCB2'''),
'FROM V_PRODUCT_STOCK',
'UNION ALL',
unistr('SELECT ''\0625\062C\0645\0627\0644\064A \0627\0644\0645\0648\0631\062F\064A\0646'', COUNT(*), ''\D83D\DE9A'''),
'FROM SUPPLIERS;'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT ''Total Products'' TITLE, COUNT(*) BODY, ''\D83D\DCE6'' ICON'),
'FROM PRODUCTS',
'UNION ALL',
unistr('SELECT ''Low Stock Products'', COUNT(*), ''\26A0\FE0F'''),
'FROM V_PRODUCT_STOCK',
'WHERE CURRENT_STOCK <= MIN_STOCK_LEVEL',
'UNION ALL',
unistr('SELECT ''Total Stock Value'', SUM(UNIT_PRICE * CURRENT_STOCK), ''\D83D\DCB2'''),
'FROM V_PRODUCT_STOCK',
'UNION ALL',
unistr('SELECT ''Total Suppliers'', COUNT(*), ''\D83D\DE9A'''),
'FROM SUPPLIERS;'))
);
wwv_flow_imp_shared.create_translation(
 p_id=>wwv_flow_imp.id(309012532640415319000)
,p_page_id=>8
,p_translated_flow_id=>190305
,p_translate_to_id=>wwv_flow_imp.id(300362482436450620448.190305)
,p_translate_from_id=>wwv_flow_imp.id(300362482436450620448)
,p_translate_column_id=>21
,p_translate_to_lang_code=>'ar-ye'
,p_translation_specific_to_item=>'NO'
,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    p.PRODUCT_ID,',
'    p.PRODUCT_NAME,',
'    c.CATEGORY_NAME,      -- instead of CATEGORY_ID',
'    s.SUPPLIER_NAME,      -- instead of SUPPLIER_ID',
'    p.UNIT_PRICE,',
'    p.MIN_STOCK_LEVEL,',
'    v.CURRENT_STOCK,',
'    v.STOCK_VALUE,',
'',
'    -- Status Column',
'    CASE  ',
'        WHEN v.CURRENT_STOCK = 0 THEN ''CRITICAL''',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN ''LOW STOCK''',
'        WHEN v.CURRENT_STOCK = p.MIN_STOCK_LEVEL THEN ''AT MIN LEVEL''',
'        ELSE ''OK''',
'    END AS STOCK_STATUS,',
'',
'    -- Shortage Quantity',
'    CASE  ',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN p.MIN_STOCK_LEVEL - v.CURRENT_STOCK',
'        ELSE 0',
'    END AS SHORTAGE_QTY,',
'',
'    -- Row Class for coloring',
'    CASE',
'        WHEN v.CURRENT_STOCK = 0 THEN ''very-critical-row''  ',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN ''critical-row''',
'        WHEN v.CURRENT_STOCK = p.MIN_STOCK_LEVEL THEN ''low-stock-row''',
'    END AS ROW_CLASS',
'',
'FROM V_PRODUCT_STOCK v',
'JOIN PRODUCTS p ON v.PRODUCT_ID = p.PRODUCT_ID',
'JOIN CATEGORIES c ON p.CATEGORY_ID = c.CATEGORY_ID',
'JOIN SUPPLIERS s ON p.SUPPLIER_ID = s.SUPPLIER_ID',
'WHERE v.CURRENT_STOCK <= p.MIN_STOCK_LEVEL',
'ORDER BY v.CURRENT_STOCK ASC;'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    p.PRODUCT_ID,',
'    p.PRODUCT_NAME,',
'    c.CATEGORY_NAME,      -- instead of CATEGORY_ID',
'    s.SUPPLIER_NAME,      -- instead of SUPPLIER_ID',
'    p.UNIT_PRICE,',
'    p.MIN_STOCK_LEVEL,',
'    v.CURRENT_STOCK,',
'    v.STOCK_VALUE,',
'',
'    -- Status Column',
'    CASE  ',
'        WHEN v.CURRENT_STOCK = 0 THEN ''CRITICAL''',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN ''LOW STOCK''',
'        WHEN v.CURRENT_STOCK = p.MIN_STOCK_LEVEL THEN ''AT MIN LEVEL''',
'        ELSE ''OK''',
'    END AS STOCK_STATUS,',
'',
'    -- Shortage Quantity',
'    CASE  ',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN p.MIN_STOCK_LEVEL - v.CURRENT_STOCK',
'        ELSE 0',
'    END AS SHORTAGE_QTY,',
'',
'    -- Row Class for coloring',
'    CASE',
'        WHEN v.CURRENT_STOCK = 0 THEN ''very-critical-row''  ',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN ''critical-row''',
'        WHEN v.CURRENT_STOCK = p.MIN_STOCK_LEVEL THEN ''low-stock-row''',
'    END AS ROW_CLASS',
'',
'FROM V_PRODUCT_STOCK v',
'JOIN PRODUCTS p ON v.PRODUCT_ID = p.PRODUCT_ID',
'JOIN CATEGORIES c ON p.CATEGORY_ID = c.CATEGORY_ID',
'JOIN SUPPLIERS s ON p.SUPPLIER_ID = s.SUPPLIER_ID',
'WHERE v.CURRENT_STOCK <= p.MIN_STOCK_LEVEL',
'ORDER BY v.CURRENT_STOCK ASC;'))
);
