,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Find the report table by Static ID',
'var report = document.querySelector("#low_stock_ir");',
'',
'// Safety check',
'if (!report) {',
'    console.warn("IR not found!");',
'    return;',
'}',
'',
'// Loop through all table rows',
'report.querySelectorAll("tbody tr").forEach(function(row) {',
'',
'    // Adjust the column index for ROW_CLASS',
'    // Example: if ROW_CLASS is the last column',
'    var rowClassCell = row.cells[row.cells.length - 1]; ',
'    if (!rowClassCell) return;',
'',
'    var rowClass = rowClassCell.innerText.trim();',
'',
'    // Apply row colors',
'    if (rowClass === "very-critical-row") {',
'        row.style.backgroundColor = "#e67b7b";  // red',
'        row.style.fontWeight = "bold";',
'    } ',
'    else if (rowClass === "critical-row") {',
'        row.style.backgroundColor = "#ffcccc";  // light red',
'    } ',
'    else if (rowClass === "low-stock-row") {',
'        row.style.backgroundColor = "#fff3cd";  // yellow',
'    }',
'});'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Find the report table by Static ID',
'var report = document.querySelector("#low_stock_ir");',
'',
'// Safety check',
'if (!report) {',
'    console.warn("IR not found!");',
'    return;',
'}',
'',
'// Loop through all table rows',
'report.querySelectorAll("tbody tr").forEach(function(row) {',
'',
'    // Adjust the column index for ROW_CLASS',
'    // Example: if ROW_CLASS is the last column',
'    var rowClassCell = row.cells[row.cells.length - 1]; ',
'    if (!rowClassCell) return;',
'',
'    var rowClass = rowClassCell.innerText.trim();',
'',
'    // Apply row colors',
'    if (rowClass === "very-critical-row") {',
'        row.style.backgroundColor = "#e67b7b";  // red',
'        row.style.fontWeight = "bold";',
'    } ',
'    else if (rowClass === "critical-row") {',
'        row.style.backgroundColor = "#ffcccc";  // light red',
'    } ',
'    else if (rowClass === "low-stock-row") {',
'        row.style.backgroundColor = "#fff3cd";  // yellow',
'    }',
'});'))
);
