,p_translate_to_text=>unistr('SELECT ''Total Products'' TITLE, COUNT(*) BODY, ''\D83D\DCE6'' ICON FROM PRODUCTS UNION ALL SELECT ''Low Stock Products'', COUNT(*), ''\26A0\FE0F'' FROM V_PRODUCT_STOCK WHERE CURRENT_STOCK <= MIN_STOCK_LEVEL UNION ALL SELECT ''Total Stock Value'', SUM(UNIT_PRICE * CURRENT_STOC')
||unistr('K), ''\D83D\DCB2'' FROM V_PRODUCT_STOCK UNION ALL SELECT ''Total Suppliers'', COUNT(*), ''\D83D\DE9A'' FROM SUPPLIERS;')
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
