prompt --application/shared_components/security/authentications/inventory_system_auth
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(305304929899841624870)
,p_name=>'Inventory_system_auth'
,p_static_id=>'inventory-system-auth'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'auth2',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- FUNCTION auth2(',
'--     p_username IN VARCHAR2,',
'--     p_password IN VARCHAR2',
'-- ) RETURN BOOLEAN',
'-- IS',
'--     l_count NUMBER;',
'-- BEGIN',
'--     SELECT COUNT(*)',
'--     INTO l_count',
'--     FROM USERS',
'--     where UPPER(TRIM(username)) = UPPER(TRIM(p_username))',
'--       AND password = apex_util.get_hash(apex_t_varchar2(p_password));',
'',
'--     RETURN l_count > 0;',
'',
'-- END auth2;',
'',
'FUNCTION auth2(',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN',
'IS',
'    l_count NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO l_count',
'    FROM USERS',
'    WHERE UPPER(TRIM(username)) = UPPER(TRIM(p_username))',
'      AND password = STANDARD_HASH(p_password, ''SHA256'');',
'',
'    RETURN l_count > 0;',
'END auth2;'))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'15742381173716'
,p_created_on=>wwv_flow_imp.dz('20260402162807Z')
,p_updated_on=>wwv_flow_imp.dz('20260402162807Z')
,p_created_by=>'FATGUBARI@GMAIL.COM'
,p_updated_by=>'FATGUBARI@GMAIL.COM'
);
end;
