prompt --application/shared_components/security/authentications/oracle_apex_accounts
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(298969673134897972239)
,p_name=>'Oracle APEX Accounts'
,p_static_id=>'oracle-apex-accounts'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'WKSP_FATIMA2026APEX.auth',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'FUNCTION auth(',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN IS',
'    l_hash       users.password%TYPE;',
'    l_input_hash users.password%TYPE;',
'BEGIN',
'    SELECT password',
'      INTO l_hash',
'      FROM users',
'      WHERE UPPER(TRIM(username)) = UPPER(TRIM(p_username));',
'',
'    SELECT STANDARD_HASH(p_password, ''SHA256'')',
'      INTO l_input_hash',
'      FROM dual;',
'',
'    IF l_input_hash = l_hash THEN',
'        RETURN TRUE;',
'    ELSE',
'        RETURN FALSE;',
'    END IF;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN FALSE; ',
'END auth;',
''))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'15742417463763'
,p_created_on=>wwv_flow_imp.dz('20260402162807Z')
,p_updated_on=>wwv_flow_imp.dz('20260402162807Z')
,p_created_by=>'FATGUBARI@GMAIL.COM'
,p_updated_by=>'FATGUBARI@GMAIL.COM'
);
end;
