 p_id=>wwv_flow_imp.id(298974801486284109946)
,p_validation_name=>'Prevent Negative Stock'
,p_static_id=>'prevent-negative-stock'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_current_stock NUMBER := 0;',
'BEGIN',
'    IF :P5_TRANSACTION_TYPE = ''OUT'' THEN',
'        ',
'        SELECT NVL(',
'               SUM(CASE ',
'                      WHEN TRANSACTION_TYPE = ''IN''  THEN QUANTITY',
'                      WHEN TRANSACTION_TYPE = ''OUT'' THEN -QUANTITY',
'                   END),0)',
'        INTO v_current_stock',
'        FROM STOCK_TRANSACTIONS',
'        WHERE PRODUCT_ID = :P5_PRODUCT_ID;',
'        ',
'        IF :P5_QUANTITY > v_current_stock THEN',
'            RETURN FALSE;',
'        END IF;',
'        ',
'    END IF;',
'',
'    RETURN TRUE;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Quantity exceeds current stock.'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
