,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    p.PRODUCT_ID,',
'    p.PRODUCT_NAME,',
'    c.CATEGORY_NAME,      -- instead of CATEGORY_ID',
'    s.SUPPLIER_NAME,      -- instead of SUPPLIER_ID',
