'    CASE  ',
'        WHEN v.CURRENT_STOCK = 0 THEN ''CRITICAL''',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN ''LOW STOCK''',
'        WHEN v.CURRENT_STOCK = p.MIN_STOCK_LEVEL THEN ''AT MIN LEVEL''',
'        ELSE ''OK''',
'    END AS STOCK_STATUS,',
'',
'    -- Shortage Quantity',
'    CASE  ',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN p.MIN_STOCK_LEVEL - v.CURRENT_STOCK',
'        ELSE 0',
'    END AS SHORTAGE_QTY,',
'',
'    -- Row Class for coloring',
'    CASE',
'        WHEN v.CURRENT_STOCK = 0 THEN ''very-critical-row''  ',
'        WHEN v.CURRENT_STOCK < p.MIN_STOCK_LEVEL THEN ''critical-row''',
'        WHEN v.CURRENT_STOCK = p.MIN_STOCK_LEVEL THEN ''low-stock-row''',
'    END AS ROW_CLASS',
'',
'FROM V_PRODUCT_STOCK v',
'JOIN PRODUCTS p ON v.PRODUCT_ID = p.PRODUCT_ID',
'JOIN CATEGORIES c ON p.CATEGORY_ID = c.CATEGORY_ID',
'JOIN SUPPLIERS s ON p.SUPPLIER_ID = s.SUPPLIER_ID',
'WHERE v.CURRENT_STOCK <= p.MIN_STOCK_LEVEL',
'ORDER BY v.CURRENT_STOCK ASC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_content_disposition=>'ATTACHMENT'
